# Code generated by Claude
"""
Tests of src/furniture_map.py (the layered furniture map, B2.9), on a made-up scene and on the real task scene. No arm maps are involved.

    MUJOCO_GL=egl python experiments/furniture_map_test.py

1. Made-up scene (a crate rotated 30 degrees, a table with a top above the base band and four thin legs, a pole, a geom that does not collide, a body that is excluded, the robot's own root
   body, a plane): each shape lands in the right layer or layers with the right area (within 5 %) and position; the non-colliding geom, the excluded body, the robot and the plane are not
   in; points outside the grid count as occupied.
2. Growth by the footprint and by the arm disc against the analytic result: a 0.2 m square obstacle, the base footprint x -0.36 to 0.34, y +-0.3 (the real chassis): the blocked area and extents
   at heading 0 and at 90 degrees; an obstacle in the arm layer is grown by the arm disc radius; the grid's edge blocks the cells whose footprint would leave it.
3. The real task scene (with the room walls now colliding): the walls are in both layers, the bench's frame in the base layer and its top in the arm layer (area 4.4 x 1.6 m), the current staging
   stance is free at its heading, a spot under the bench top is blocked by the arm layer, open floor is free, and the scene's robot is left out.
"""

import math
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import mujoco  # noqa: E402
import numpy as np  # noqa: E402

from src.furniture_map import FurnitureMap, footprint_polygon, geom_points_world  # noqa: E402
from src.stance_finder import robot_geometry  # noqa: E402
from src.task_beaker_hotplate import load_task  # noqa: E402
from src.staging_source import staging_approach_xy  # noqa: E402
from src.task_config import FURNITURE_CFG, TASK_CFG  # noqa: E402

results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


XML = """
<mujoco><worldbody>
  <geom name="floor" type="plane" size="5 5 0.1"/>
  <body name="base_link" pos="3 3 0.3"><freejoint/><geom type="box" size="0.3 0.3 0.1"/></body>
  <body name="crate" pos="1 2 0.15"><geom type="box" size="0.2 0.1 0.15" euler="0 0 30"/></body>
  <body name="table" pos="-2 1 0">
    <geom name="top" type="box" pos="0 0 0.85" size="0.5 0.3 0.05"/>
    <geom type="box" pos="0.45 0.25 0.4" size="0.02 0.02 0.4"/><geom type="box" pos="-0.45 0.25 0.4" size="0.02 0.02 0.4"/>
    <geom type="box" pos="0.45 -0.25 0.4" size="0.02 0.02 0.4"/><geom type="box" pos="-0.45 -0.25 0.4" size="0.02 0.02 0.4"/>
  </body>
  <body name="pole" pos="2 -2 1"><geom type="cylinder" size="0.1 1.0"/></body>
  <body name="ghost" pos="0 -1 0.2"><geom type="box" size="0.3 0.3 0.2" contype="0" conaffinity="0"/></body>
  <body name="target" pos="-1 -3 0.2"><geom type="box" size="0.1 0.1 0.2"/></body>
</worldbody></mujoco>
"""
CFG = {**FURNITURE_CFG, "bounds": (-4.0, 4.0, -4.0, 4.0)}


def area(layer, m):
    return float(m.layers[layer].sum()) * m.res ** 2


def region_area(layer, m, x0, x1, y0, y1):
    iy0, ix0, _ = m.cell_of(np.array([[x0, y0]]))
    iy1, ix1, _ = m.cell_of(np.array([[x1, y1]]))
    return float(m.layers[layer][iy0[0]:iy1[0], ix0[0]:ix1[0]].sum()) * m.res ** 2


def extent(mask, m):
    iy, ix = np.nonzero(mask)
    return (m.origin[0] + ix.min() * m.res, m.origin[0] + (ix.max() + 1) * m.res, m.origin[1] + iy.min() * m.res, m.origin[1] + (iy.max() + 1) * m.res)


def main():
    print("\n1. made-up scene")
    model = mujoco.MjModel.from_xml_string(XML)
    data = mujoco.MjData(model)
    fm = FurnitureMap.from_model(model, data, CFG, exclude_bodies=("target",))
    a = region_area("base", fm, 0.5, 1.5, 1.5, 2.5)
    check("the crate (0.4 x 0.2 m, 0.3 m tall, turned 30 degrees) is in the base layer with its area", abs(a - 0.08) < 0.004, f"{a:.4f} m^2")
    check("the crate is not in the arm layer", region_area("arm", fm, 0.5, 1.5, 1.5, 2.5) == 0)
    a = region_area("arm", fm, -3, -1, 0, 2)
    check("the table top (1.0 x 0.6 m at 0.8 to 0.9 m) is in the arm layer with its area", abs(a - 0.6) < 0.03, f"{a:.3f} m^2")
    check("the table top is not in the base layer: only its four legs are", abs(region_area("base", fm, -3, -1, 0, 2) - 4 * 0.04 ** 2) < 0.002 and not fm.occupied("base", np.array([[-2.0, 1.0]]))[0], f"{region_area('base', fm, -3, -1, 0, 2):.4f} m^2")
    ap, bp = region_area("arm", fm, 1.5, 2.5, -2.5, -1.5), region_area("base", fm, 1.5, 2.5, -2.5, -1.5)
    check("the pole (radius 0.1 m, 2 m tall) is in both layers with its area", abs(ap - math.pi * 0.01) < 0.002 and abs(bp - math.pi * 0.01) < 0.002, f"{bp:.4f} and {ap:.4f} m^2")
    check("the non-colliding geom is not in", not fm.occupied("base", np.array([[0.0, -1.0]]))[0] and not fm.occupied("arm", np.array([[0.0, -1.0]]))[0])
    check("the excluded body, the robot's root body and the plane are not in", not fm.occupied("base", np.array([[-1.0, -3.0], [3.0, 3.0], [0.0, 0.0]])).any())
    check("points outside the grid count as occupied", fm.occupied("base", np.array([[5.0, 0.0], [0.0, -4.5]])).all())
    cen = fm.cell_of(np.array([[1.0, 2.0]]))
    check("the crate sits at its position", fm.occupied("base", np.array([[1.0, 2.0]]))[0] and not fm.occupied("base", np.array([[1.4, 2.0]]))[0])

    print("\n2. growth by the footprint and the arm disc")
    base = np.zeros((800, 800), bool)
    armm = np.zeros((800, 800), bool)
    res = 0.01
    base[400 - 10:400 + 10, 400 - 10:400 + 10] = True                    # a 0.2 m square at the origin
    armm[200 - 10:200 + 10, 200 - 10:200 + 10] = True                    # another at (-2, -2)
    sm = FurnitureMap({"base": base, "arm": armm}, (-4.0, -4.0), res, 0.25)
    fp = np.array([[-0.36, -0.3], [0.34, -0.3], [0.34, 0.3], [-0.36, 0.3]])
    b0 = sm.blocked(0.0, fp)
    sel = np.zeros_like(b0)
    sel[300:500, 300:500] = True                                          # around the base layer obstacle only
    bb = b0 & sel
    x0, x1, y0, y1 = extent(bb, sm)
    check("heading 0: the blocked area around the obstacle is the Minkowski sum (0.2 + 0.70) x (0.2 + 0.60)", abs(bb.sum() * res ** 2 - 0.9 * 0.8) < 0.02, f"{bb.sum() * res ** 2:.3f} m^2")
    check("heading 0: its extents are -0.44 to 0.46 in x and -0.40 to 0.40 in y", abs(x0 + 0.44) < 0.02 and abs(x1 - 0.46) < 0.02 and abs(y0 + 0.40) < 0.02 and abs(y1 - 0.40) < 0.02, f"x {x0:.2f}..{x1:.2f}, y {y0:.2f}..{y1:.2f}")
    b90 = sm.blocked(math.pi / 2, fp) & sel
    x0, x1, y0, y1 = extent(b90, sm)
    check("heading 90 degrees: extents -0.40 to 0.40 in x and -0.44 to 0.46 in y", abs(x0 + 0.40) < 0.02 and abs(x1 - 0.40) < 0.02 and abs(y0 + 0.44) < 0.02 and abs(y1 - 0.46) < 0.02, f"x {x0:.2f}..{x1:.2f}, y {y0:.2f}..{y1:.2f}")
    sel2 = np.zeros_like(b0)
    sel2[100:300, 100:300] = True
    ba = b0 & sel2
    x0, x1, y0, y1 = extent(ba, sm)
    check("an arm layer obstacle is grown by the 0.25 m disc: a 0.2 m square becomes about 0.7 m wide", abs((x1 - x0) - 0.70) < 0.03 and abs((y1 - y0) - 0.70) < 0.03, f"{x1 - x0:.2f} x {y1 - y0:.2f} m")
    check("the grid's edge blocks the cells whose footprint would leave it", b0[0, 400] and b0[400, 0] and b0[-1, 400] and b0[400, -1] and not b0[100, 700])

    print("\n3. the real task scene")
    sim = load_task({**TASK_CFG, "bench_open": False}, cameras=False)                  # the solid bench (frame rails included)
    m, d = sim.model, sim.data
    real = FurnitureMap.from_model(m, d, FURNITURE_CFG, exclude_bodies=("task_beaker",))
    wall_cells = [[5.99, 0.0], [-5.99, 0.0], [0.0, 5.99], [0.0, -5.99]]
    check("the four room walls are in both layers", real.occupied("base", np.array(wall_cells)).all() and real.occupied("arm", np.array(wall_cells)).all())
    a_top = region_area("arm", real, -2.3, 2.3, -0.9, 0.9)
    check("the bench top is in the arm layer: 4.4 x 1.6 m", abs(a_top - 4.4 * 1.6) < 0.4, f"{a_top:.2f} m^2 inside the box (the objects on it add a little)")
    check("the bench frame is in the base layer, its inside is not", real.occupied("base", np.array([[0.0, 0.78], [-2.18, 0.0]])).all() and not real.occupied("base", np.array([[0.0, 0.0]]))[0])
    robot = robot_geometry(m)
    fp = robot["footprint"]
    check("the base footprint polygon is the chassis (x about -0.36 to 0.34, y about +-0.30)", abs(fp[:, 0].min() + 0.363) < 0.01 and abs(fp[:, 0].max() - 0.341) < 0.01 and abs(fp[:, 1].max() - 0.305) < 0.01, f"x {fp[:, 0].min():.3f}..{fp[:, 0].max():.3f}, y {fp[:, 1].min():.3f}..{fp[:, 1].max():.3f}")
    sx, sy = TASK_CFG["staging_xy"]
    yaw = TASK_CFG["staging_yaw"]
    bl = real.blocked(yaw, fp)
    ax, ay = staging_approach_xy(TASK_CFG)
    iy, ix, _ = real.cell_of(np.array([[ax, ay]]))
    check("the approach spot (21 cm behind the staging stance) is free at its heading on the solid bench", not bl[iy[0], ix[0]])
    iy, ix, _ = real.cell_of(np.array([[sx, sy]]))
    check("the staging stance is blocked on the solid bench (its chassis would be under the frame rails: it is a stance for the open bench, design plan 4.1)", bl[iy[0], ix[0]])
    iy, ix, _ = real.cell_of(np.array([[sx, 0.6]]))
    check("a spot under the bench top (0.6 m from its centre line) is blocked", bl[iy[0], ix[0]])
    iy, ix, _ = real.cell_of(np.array([[3.0, 3.5]]))
    check("open floor (3, 3.5) is free", not bl[iy[0], ix[0]])
    check("the robot's own geoms are not in the map (the spawn point is free)", not real.occupied("base", np.array([TASK_CFG["spawn_xy"]]))[0])

    print("\n4. the open bench (TASK_CFG default since 2026-10-19) and the column kernel")
    del sim, m, d
    sim = load_task(cameras=False)
    m, d = sim.model, sim.data
    op = FurnitureMap.from_model(m, d, FURNITURE_CFG, exclude_bodies=("task_beaker",))
    check("open bench: the frame is gone from the base layer, the legs stay", not op.occupied("base", np.array([[0.0, 0.78], [-2.18, 0.0], [0.0, 0.0]])).any() and op.occupied("base", np.array([[2.0, 0.7], [-2.0, -0.7]])).all())
    check("open bench: the top is still in the arm layer", op.occupied("arm", np.array([[0.0, 0.0], [0.0, 0.78], [1.5, 0.5]])).all())
    robot = robot_geometry(m)
    col = robot["column"]
    check("the column function exists and its slab is the bench top's underside to its surface", col is not None and abs(robot["column_slab"][0] - 0.84) < 1e-6 and abs(robot["column_slab"][1] - 0.96) < 1e-6, str(robot["column_slab"]))
    for q in (0.0, 0.2, 0.418):
        poly = col(q)
        print(f"     pedestal command {q}: column cross-section at the bench top's height x {poly[:, 0].min():+.3f}..{poly[:, 0].max():+.3f} y {poly[:, 1].min():+.3f}..{poly[:, 1].max():+.3f} (with the 2 cm margin)")
    yaw = TASK_CFG["staging_yaw"]
    sx, sy = TASK_CFG["staging_xy"]
    ax, ay = staging_approach_xy(TASK_CFG)
    b_open = op.blocked(yaw, robot["footprint"], col(TASK_CFG["pedestal_q"]))                 # the open-bench map with the column's real cross-section (design plan 3.4)
    iy, ix, _ = op.cell_of(np.array([[sx, sy]]))
    check("the staging stance is free at its heading on the open bench (column kernel, the stance's pedestal height)", not b_open[iy[0], ix[0]])
    iy, ix, _ = op.cell_of(np.array([[ax, ay]]))
    check("the approach spot is free at its heading on the open bench", not b_open[iy[0], ix[0]])
    p0 = col(0.0)
    check("the column cross-section is a real polygon smaller than the old 0.25 m disc", len(p0) >= 3 and np.abs(p0).max() < 0.25, f"largest coordinate {np.abs(p0).max():.3f}")
    fp = robot["footprint"]
    yaw = -math.pi / 2
    b_disc, b_col = op.blocked(yaw, fp), op.blocked(yaw, fp, col(0.0))
    check("the column kernel blocks less than the disc (and never more)", (b_col & ~b_disc).sum() == 0 and b_col.sum() < b_disc.sum(), f"{int(b_col.sum())} vs {int(b_disc.sum())} cells")
    xi = int((0.9 - op.origin[0]) / op.res)
    ys = np.nonzero(~b_col[:, xi] & (np.arange(op.shape[0]) * op.res + op.origin[1] > 0.0))[0]
    y_min = op.origin[1] + (ys.min() + 0.5) * op.res
    front = y_min + min(math.sin(yaw) * kx + math.cos(yaw) * ky for kx, ky in col(0.0))
    check("facing the bench at q = 0 the base may go until the column is 2 cm from the bench's front edge (open bench)", abs((front - 0.80) - 0.0) < 0.025, f"column front {100 * (front - 0.80):.1f} cm from the edge (the 2 cm margin is in the polygon)")
    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    sys.exit(0 if main() else 1)
